// `npm run sql` — joins the migrations into supabase/all-in-one.sql so the whole database can be set up with one paste in the Supabase SQL editor.
const fs = require('node:fs');
const path = require('node:path');

const dir = path.join(__dirname, '..', 'supabase', 'migrations');
const files = fs.readdirSync(dir).filter((f) => f.endsWith('.sql')).sort();
const out = [
  '-- NutriBharat AI: complete database setup. Generated by `npm run sql` from supabase/migrations/*.sql — do not edit by hand.',
  '-- Run it ONCE on a new, empty Supabase project (SQL editor -> New query -> paste -> Run).',
  '',
  ...files.flatMap((f) => [`-- ======================================================== ${f}`, fs.readFileSync(path.join(dir, f), 'utf8').trim(), '']),
].join('\n');
fs.writeFileSync(path.join(__dirname, '..', 'supabase', 'all-in-one.sql'), out);
console.log(`wrote supabase/all-in-one.sql from ${files.length} migrations`);
